/**
 * The API contract: a committed snapshot of the monolith's OpenAPI document, the types
 * generated from it and the operations table the client's guard reads.
 *
 *   pnpm api:sync [--allow-dirty]   snapshot the running monolith (pnpm stack:up there),
 *                                   record its commit, regenerate
 *   pnpm api:check                  offline: generated files match the snapshot, and the
 *                                   snapshot came from a clean monolith commit (CI)
 *
 * contracts/monolith/source.json works like a lockfile: CI checks out that monolith
 * commit, starts it, and the e2e global setup asserts its live document equals the
 * snapshot. --allow-dirty is for the local loop right after `pnpm new:module` there; it
 * marks source.json dirty, so api:check fails until a clean sync.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { request } from 'node:https';
import { join } from 'node:path';
import { parseArgs } from 'node:util';
import { monolithDir, ROOT, readMonolithRegistry, readRegistry, run } from './lib.ts';

const SNAPSHOT = join(ROOT, 'contracts/monolith/openapi.json');
const SOURCE = join(ROOT, 'contracts/monolith/source.json');
const OPERATIONS = join(ROOT, 'src/platform/api/generated/operations.ts');
const METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];

interface OpenApiDocument {
  security?: unknown[];
  paths: Record<string, Record<string, { security?: unknown[] } | unknown>>;
}

/** `METHOD /path/{param}` -> 'none' (public) or 'bearer', from each operation's `security`. */
export function operationsTable(document: OpenApiDocument): string {
  const rows: string[] = [];
  for (const [path, item] of Object.entries(document.paths)) {
    for (const [method, operation] of Object.entries(item)) {
      if (!METHODS.includes(method)) continue;
      const security = (operation as { security?: unknown[] }).security ?? document.security ?? [];
      rows.push(
        `  '${method.toUpperCase()} ${path}': '${security.length === 0 ? 'none' : 'bearer'}',`,
      );
    }
  }
  return [
    '// Generated by `pnpm api:sync` from contracts/monolith/openapi.json. Do not edit.',
    '// Each operation of the API and whether it takes a bearer token: the client guard',
    '// (src/platform/api/client.ts) refuses unknown operations and any token mismatch.',
    'export const OPERATIONS = {',
    ...rows.sort(),
    "} as const satisfies Readonly<Record<string, 'none' | 'bearer'>>;",
    '',
  ].join('\n');
}

function fetchDocument(url: string, ca: Buffer): Promise<string> {
  return new Promise((resolve, reject) => {
    const req = request(url, { ca, timeout: 10_000 }, (response) => {
      let body = '';
      response.on('data', (chunk: Buffer) => {
        body += chunk.toString();
      });
      response.on('end', () =>
        response.statusCode === 200
          ? resolve(body)
          : reject(new Error(`${url} answered ${response.statusCode}`)),
      );
    });
    req.on('timeout', () => req.destroy(new Error(`${url} timed out`)));
    req.on('error', reject);
    req.end();
  });
}

const generate = (mode: 'generate' | 'check') =>
  run('pnpm', ['--silent', '--filter', '@gaw/api-codegen', mode]);

async function sync(allowDirty: boolean): Promise<void> {
  const dir = monolithDir();
  const dirty = run('git', ['status', '--porcelain'], dir).trim() !== '';
  if (dirty && !allowDirty) {
    throw new Error(
      `${dir} has uncommitted changes; commit them first (or pass --allow-dirty for a local try)`,
    );
  }
  const commit = run('git', ['rev-parse', 'HEAD'], dir).trim();
  const url = `https://localhost:${readMonolithRegistry().api.httpsPort}/openapi.json`;
  const text = await fetchDocument(url, readFileSync(join(dir, '.certs/dev-ca.pem'))).catch(
    (error: unknown) => {
      throw new Error(`cannot read ${url} (run \`pnpm stack:up\` in ${dir}): ${String(error)}`);
    },
  );
  const document = JSON.parse(text) as OpenApiDocument;
  writeFileSync(SNAPSHOT, `${JSON.stringify(document, null, 2)}\n`);
  writeFileSync(
    SOURCE,
    `${JSON.stringify(
      { repo: readRegistry().monolith.repo, commit, dirty, syncedAt: new Date().toISOString() },
      null,
      2,
    )}\n`,
  );
  generate('generate');
  writeFileSync(OPERATIONS, operationsTable(document));
  console.log(
    `api:sync: ${Object.keys(document.paths).length} paths from ${commit.slice(0, 7)}${dirty ? ' (dirty)' : ''}`,
  );
}

function check(): void {
  const problems: string[] = [];
  const document = JSON.parse(readFileSync(SNAPSHOT, 'utf8')) as OpenApiDocument;
  try {
    generate('check');
  } catch {
    problems.push('src/platform/api/generated/schema.d.ts is stale: run pnpm api:sync');
  }
  if (readFileSync(OPERATIONS, 'utf8') !== operationsTable(document)) {
    problems.push('src/platform/api/generated/operations.ts is stale: run pnpm api:sync');
  }
  const source = JSON.parse(readFileSync(SOURCE, 'utf8')) as { dirty?: boolean; commit?: string };
  if (source.dirty !== false || !/^[0-9a-f]{40}$/.test(source.commit ?? '')) {
    problems.push(
      'contracts/monolith/source.json is not from a clean monolith commit: run pnpm api:sync',
    );
  }
  if (problems.length > 0) {
    console.error(
      `api:check: ${problems.length} problem(s)\n${problems.map((p) => `  - ${p}`).join('\n')}`,
    );
    process.exit(1);
  }
  console.log('api:check: generated client matches the snapshot of a clean monolith commit');
}

if (import.meta.main) {
  const { values } = parseArgs({
    options: {
      check: { type: 'boolean', default: false },
      'allow-dirty': { type: 'boolean', default: false },
    },
  });
  if (values.check) check();
  else await sync(values['allow-dirty']);
}
